<?php require_once __DIR__.'/lib.php';$projects=db()->query("SELECT p.*,COUNT(f.id) findings FROM projects p LEFT JOIN audit_findings f ON f.project_id=p.id GROUP BY p.id ORDER BY p.created_at DESC")->fetchAll();?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>เอกสารตรวจ</title><link rel="stylesheet" href="assets/style.css"></head><body><?php include 'partials/nav.php';?><main class="container"><div class="page-title"><div class="eyebrow">AUDIT ARCHIVE</div><h1>เอกสารตรวจทั้งหมด</h1><p>ประวัติการตรวจและผลตรวจที่บันทึกไว้</p></div><div class="toolbar"><a class="btn btn-primary" href="upload.php">＋ อัปโหลดเล่มใหม่</a></div><div class="table-wrap"><table><thead><tr><th>ชื่อหลักสูตร</th><th>ระดับ</th><th>ประเภท</th><th>วันที่อัปโหลด</th><th>ประเด็น</th><th></th></tr></thead><tbody><?php foreach($projects as $p):?><tr><td><?=h($p['title'])?></td><td><?=h($p['program_type'])?></td><td><?=h($p['program_kind'])?></td><td><?=h(date('d/m/Y H:i',strtotime($p['created_at'])))?></td><td><?=$p['findings']?></td><td><a class="btn btn-outline" href="project.php?id=<?=$p['id']?>">เปิดผลตรวจ →</a></td></tr><?php endforeach;?><?php if(!$projects):?><tr><td colspan="6">ยังไม่มีข้อมูล</td></tr><?php endif;?></tbody></table></div><footer>SKRU OBE-QA Smart Audit</footer></main></body></html>